#!/bin/bash
set -e

# Nebflow cross-platform installer (macOS / Linux) — script v2
# ---------------------------------------------------------------
# SCRIPT_VERSION : installer version (written into the local install
#                  manifest for `nebflow update` and diagnostics).
# Pipeline       : [1/6] env detect -> [2/6] deps (curl/JDK/rg/voice) ->
#                  [3/6] jar -> [4/6] wrapper+PATH -> [5/6] config ->
#                  [6/6] done.
# Idempotent     : safe to re-run; installed/satisfied deps are detected
#                  and skipped.
# Flags          : --beta | --channel=beta | --cn | --global | --verbose |
#                  --banner-only (dry: print the brand banner and exit)
#                  (curl|bash pipe: env CHANNEL=beta / REGION=cn /
#                  NEBFLOW_VERBOSE=1 / NEBFLOW_BANNER_IMAGE=off|osc|sixel /
#                  NEBFLOW_BANNER_THEME=dark|light / NEBFLOW_UI_LEVEL=0..3)
# Exit codes     : 0 ok | 10 version resolve | 11 java install |
#                  12 jar download | 13 no curl/wget
# ---------------------------------------------------------------

# -- Brand values (L2 rebrand): rendered from repo-root brand.conf at -------
# -- release time (scripts/render-brand.sh); do not edit by hand. -----------
# The runtime dual-reads legacy names (L3), so rendering NEW values here
# keeps existing user data working - old dirs/env/config fall back.
PRODUCT_NAME=stand
LOWER_NAME=stand
COS_BUCKET=nebflow-releases
HOME_DIR=.stand
CONFIG_FILE=nebflow.json
WRAPPER_NAME=stand
COS_BASE_CN="https://${COS_BUCKET}.oss-cn-hangzhou.aliyuncs.com"
# Batch 2 (v2): all third-party deps mirrored on the above endpoint under the
# deps/ prefix (single primary source for every region; upstream sources
# demoted to fallback). Integrity via deps/checksums.txt (sha256, generated by
# scripts/upload-deps.sh at upload time).
COS_DEPS_BASE="${COS_BASE_CN}/deps"
# 单一源结论不变：Nebflow jar 下载/版本解析统一走上面的镜像端点
# （与 CI 两轨、线上件的端点同值）。过时理由已更正（2026-09-17）：
# 原注释写「仓库已转 private（#29，2026-09-01）⇒ GitHub Releases 未认证
# 下载 404」——仓库现已公开，该理由不再成立，GH 回退路径也不再保留；
# 维持单源的真实理由是国内可达性与带宽（GitHub 直连下载实测不可用）。
# 第三方依赖（Homebrew/ripgrep/HuggingFace 模型/favicon 连通性测试）
# 与仓库可见性无关，仍走各自公共源。

SCRIPT_VERSION="2.0.0"
RG_VERSION="14.1.1"
JDK_MAJOR_REQUIRED=21   # runtime floor
ERR_VERSION=10
ERR_JAVA=11
ERR_JAR=12
ERR_CURL=13

# -- unified log helpers ----------------------------------------------------
VERBOSE="${NEBFLOW_VERBOSE:-0}"
log_i()    { echo "[i] $*"; }
log_ok()   { echo "[ok] $*"; }
log_warn() { echo "[warn] $*"; }
log_err()  { echo "[err] $*" >&2; }
# log_v writes to stderr: verbose traces must never pollute stdout captured
# via command substitution (under VERBOSE=1 a stdout log_v inside
# $(fetch_checksum_for ...) corrupted the expected-hash capture and forced
# checksum verdicts off - an integrity-relevant capture bug).
log_v()    { if [ "$VERBOSE" = "1" ]; then echo "[v] $*" >&2; fi; }
stage_hdr(){ echo ""; echo "==> [$1/6] $2"; }

# Integrity-verification policy for third-party deps (NEBFLOW_VERIFY env,
# default warn):
#   strict = refuse unverified artifacts (the download fails when no usable
#            checksum can be obtained from deps/checksums.txt)
#   warn   = proceed, but print a VISIBLE warning for every unverified
#            artifact - degraded verification is never silent
#   off    = skip verification entirely (a one-time notice is still printed)
VERIFY_MODE=$(printf '%s' "${NEBFLOW_VERIFY:-warn}" | tr '[:upper:]' '[:lower:]')
case "$VERIFY_MODE" in
    strict|warn|off) : ;;
    *) VERIFY_MODE="warn" ;;
esac

# Parse flags
CHANNEL="stable"
for arg in "$@"; do
    case "$arg" in
        --beta|--channel=beta) CHANNEL="beta" ;;
        --cn) REGION="cn" ;;
        --global) REGION="global" ;;
        --verbose) VERBOSE=1 ;;
        --banner-only) BANNER_ONLY=1 ;;
    esac
done

# Resolve version — 镜像版本文件（单一源）。
# 2026-09-17 更正：这里曾写「GH API private 后不可用」——仓库现已公开，
# 该理由过时；GH API 分支退役的原因是单源口径本身，与仓库可见性无关。
resolve_version() {
    if [ "$CHANNEL" = "beta" ]; then
        log_i "Resolving latest beta version..."
        if [ -z "$VERSION" ]; then
            BETA_TAG=$(curl -fsSL --connect-timeout 5 --max-time 10 \
                "${COS_BASE_CN}/latest-beta-version.txt" 2>/dev/null || true)
            if [ -z "$BETA_TAG" ]; then
                log_err "Could not find a beta release (COS version file unreachable)."
                log_err "Check ${COS_BASE_CN}/latest-beta-version.txt"
                exit $ERR_VERSION
            fi
            VERSION="$BETA_TAG"
        fi
    else
        log_i "Resolving latest stable version..."
        if [ -z "$VERSION" ]; then
            LATEST_VERSION=$(curl -fsSL --connect-timeout 5 --max-time 10 \
                "${COS_BASE_CN}/latest-version.txt" 2>/dev/null || true)
            if [ -z "$LATEST_VERSION" ]; then
                log_err "Could not resolve latest version (COS version file unreachable)."
                log_err "Check ${COS_BASE_CN}/latest-version.txt"
                exit $ERR_VERSION
            fi
            VERSION="$LATEST_VERSION"
        fi
    fi
    # 版本值双形态解析（作者令 2026-09-17）：发布 tag 版式统一无 v（如
    # 2026.9.19），但旧形态（指针文件或手工传入的 v2026.9.19）仍必须接受——
    # 解析后统一剥离前导 v，使 jar 名 / URL / 安装目录在两种形态下完全一致；
    # 本就无前缀的值逐字节不变（幂等，纯字符串处理，无网络/无分支扩张）。
    case "$VERSION" in
        v[0-9]*)
            log_v "VERSION carried the legacy 'v' prefix - normalized to ${VERSION#v}."
            VERSION="${VERSION#v}"
            ;;
    esac
    log_v "Resolved VERSION=${VERSION} (channel=${CHANNEL})"
}

# Install base (再生治本批 2026-10-22): STAND_HOME is the first-priority base,
# default is the brand home (~/.stand). NEBFLOW_HOME is deliberately NOT
# consulted here - the installer NEVER writes the legacy ~/.nebflow root; the
# legacy name is read-only compat handled by the runtime (nebflow.shared.paths
# resolveDefaultDataRoot), never by installation. A fresh install therefore
# touches zero ~/.nebflow paths.
STAND_BASE="${STAND_HOME:-${HOME}/${HOME_DIR}}"
INSTALL_DIR="${INSTALL_DIR:-${STAND_BASE}/bin}"

# >>> BRAND-UI-BEGIN (official-logo banner: stand-horizontal lockup + progress bar) >>>
# Brand banner: the OFFICIAL stand-horizontal lockup (symbol + wordmark, the
# composition the website navbar renders) reproduced in the terminal. DUAL
# PATH (2026-10-22 image-protocol batch), same official payloads on both:
#
#   image path  - the REAL logo raster when the terminal speaks an inline-
#                 image protocol: OSC 1337 (iTerm2 / WezTerm / mintty /
#                 Konsole >= 22.04) via BANNER_PNG_DARK/LIGHT (base64 PNG,
#                 width/height declared in CELLS pins it onto the art grid),
#                 or SIXEL (Windows Terminal >= 1.22 via WT_SESSION, foot,
#                 xterm) via BANNER_SIXEL_DARK/LIGHT (pre-encoded body, DCS/
#                 ST framing added at runtime - pure printable ASCII in the
#                 file). P2=1 keeps unpainted pixels transparent.
#   art fallback - U+2580/U+2584/U+2588 half-block glyphs driven by
#                 BANNER_ART (auto-sampled from the authoritative
#                 Illustrator-kit SVGs by scripts/render-install-banner.py -
#                 rasterize -> alpha-coverage threshold -> half-block cells ->
#                 RLE; no hand-drawn approximation, author mandate
#                 2026-10-22: the retired 4x3 green-pixel "S" mask did not
#                 match the brand - no green remains; the kit is pure
#                 monochrome ink). Old conhost / dumb pipes / every terminal
#                 without an image protocol render this path.
#
# BANNER_ART is a 1-bit coverage grid of the lockup, run-length encoded as
# <count><cell> tokens with rows joined ';'. Cell codes: '.' empty, 'u' ink
# upper half, 'n' ink lower half, '#' ink full cell. Ink is painted with the
# FOREGROUND color so the terminal's own background shows through - the art
# keeps the kit's transparency on every terminal. BANNER_INK_DARK/LIGHT are
# the two kit variants' true fill values (24-bit truecolor): white-ink variant
# on dark terminals, black-ink variant on light terminals.
# Anti-drift: scripts/check-logo-matrix.py re-derives ALL embedded payloads
# from the SVGs and asserts both installers embed them byte-identically.
#
# Degrade chain (art path): truecolor fg (3) -> xterm-256 fg (2) -> 16-color
# fg (1) -> mono # mask (0), every level keeps the shape. The half-block
# glyphs are UTF-8 (U+2580/84/88): without a UTF-8 locale the banner degrades
# to mono, the same rule the progress bar's eighth-blocks follow.
# Width discipline: 72 cells + 2-space indent = 74 columns, inside the
# 80-column terminal floor. The grid is 72 columns x 9 half-block rows (each
# cell carries two pixel rows), physically 4:1 - a terminal cell is ~2x taller
# than wide - which reproduces the lockup's 4.007:1 aspect. The image payloads
# target the same footprint (OSC 1337 declares 72x9 CELLS; the sixel canvas
# is 576x~144 px = 72x9 cells at an ~8x16 cell raster).
#   guards: NO_COLOR / CI / non-TTY / TERM=dumb -> art path, mono (plain text)
#   image : NEBFLOW_BANNER_IMAGE=off -> force art; =osc|sixel -> force that
#           protocol (testing; bypasses every guard); unset -> auto-detect.
#           Auto honors the same guards as the color levels - a redirected
#           pipe never swallows sixel/OSC bytes.
#   theme : NEBFLOW_BANNER_THEME=dark|light overrides; else COLORFGBG's
#           background field (>=7 means a light background); default dark
#   level : NEBFLOW_UI_LEVEL=0..3 forces a level (preview/testing)
#   dry   : --banner-only / NEBFLOW_BANNER_ONLY=1 prints the banner and exits
#           (renders with VERSION=${VERSION:-dev}; zero network, zero install
#           side effects - the render-function-standalone testability rule)

# >>> BANNER-ART-BEGIN (generated by scripts/render-install-banner.py -- do not hand-edit) >>>
# Official stand-horizontal lockup (symbol + wordmark), auto-sampled
# from src/main/resources/web/brand/stand/illustrator/svg/ by
# scripts/render-install-banner.py (1-bit coverage, RLE cells:
# '.' empty | 'u' ▀ top | 'n' ▄ bottom | '#' █ full; rows joined ';').
BANNER_ART="15.5n52.;9.3n5#2u53.;5.2n4#3u11.7n2.8n3.2n5.1n6.2n1.8n2.;2.1n5#1u15.2#5u2.3u2#3u2.1n3#1n4.3#1n3.2#1.2#5u2#1.;2.5#3.3u4#2n5.6u2#1n3.2#4.2#1u2.2#1n2.2#2u1#2n2#1.2#5.2#1.;3.7u3.1n5#4.2n7#1u3.2#2.1n1#1u5.1u1#1n1.2#3.1u3#1.8#1u1.;9.2n5#2u54.;3.2n6#3u58.;2.5u65."
BANNER_INK_DARK="255;255;255"    # white-ink kit variant (dark terminals)
BANNER_INK_LIGHT="0;0;0"      # black-ink kit variant (light terminals)
# image path payloads (iTerm2/WezTerm/mintty/konsole OSC 1337 + sixel:
# Windows Terminal 1.22+/foot/...; old conhost never sees them - the
# block art above is its fallback). Single-quoted: the sixel charset
# (0x3F-0x7E) can never hold a quote, the DCS/ST framing is added at
# runtime so this file stays pure printable ASCII.
BANNER_PNG_DARK=""
BANNER_PNG_LIGHT=""
BANNER_SIXEL_DARK='"1;1;576;144#1;2;100;100;100-!576?-!126?!5_!5o!5w!7{!11}~~~^NNFB@!408?-!104?___ooo!4w!4{!4}!33~^NFBB@!415?-!85?___ooowww{{{!4}!44~^^^NFFB@!423?-!70?__oooww{{{}}}!43~^^^NNN!4FBBB@@@!434?-!56?___ooww{{}}!42~^^^NNNFFFBBB@@!453?-!45?_ooww{{}}!40~^^NNNFFBBB@@!470?-!35?_oow{{}}!38~^^NNFFBB@@@!104?_oowww!55{[KC!5?_ow!66{[KC!19?_o!16{o_!39?!13{wo__!42?!13{!5?CK!65{wwoo_!12?-!27?_ow{{}!37~^^NFFBB@@!112?_o{}!54~^NNFB@!5?_ow{}!63~^NFB@!18?_ow}!22~{w_!35?!18~}{{wo_!35?!13~!8?@BF!67~}wo!8?-!20?_ow{}!37~^NFBB@!122?w!14~NBB!40@!11?!31@B!13~!23@!19?_ow}!13~^NFN!14~}wo_!30?!26~}{woo_!27?!13~!11?!14~!36@BBBFN^!15~{!6?-!16?_o{}!36~^FB@!27?!5_!5o!25w!4o!5_!59?N!14~}{w!43o__!38?!13~!37?_ow{!14~NFB@!5?@BN^!13~}{w_!26?!13~BFNN^!15~}}{wo__!19?!13~!11?!14~!43?!15~!6?-!15?{!37~^B!18?_ooWW[[[]]M!10N!7^!34~}}{{{wwo__!46?@FN^!60~}{w_!32?!13~!33?ow{}!13~^NB@!15?BFN!14~{wo!22?!13~!6?@@BFNN^!15~}{wwo_!12?!13~!11?!14~!43?!15~!6?-!15?N!37~{_!49?@@BFFN!36~}{wo!46?@BBB!42FNN^!14~}!31?!13~!28?ow{}!13~^NF@!24?@BN^!13~}{o_!17?!13~!14?@@BFNN^!15~}{woo_!4?!13~!11?!14~!43?!15~!6?-!17?@BNN^!34~}}{wwwooo!6_!12?!7_oOO!18?v!39~w!91?_o!15~!31?!13~!23?_w{}!13~^NFB!34?BFN!13~}{w_!13?!13~!22?@@BFNN^!14~}{{!13~!11?!14~!38?__ow}!14~^!6?-!24?@BBBFFNNN!5^!35~!4^!4NFFFBBB@@!18?_ow}!38~^N!40?__ow{{}!59~^NB!31?!12~^!18?_o{}!14~NFB@!42?@BN^!13~}wo_!8?!13~!30?@@BFNN^!22~!11?!67~^NF@!7?-!43?!23@!33?__oow{}!39~^NF@!34?_oow{}}!58~^^^NNFB@@!34?!5~^NNFB@!15?ow{}!14~^FB@!52?BFN^!12~}{o_!4?!13~!38?@BBFN^^!14~!11?^!56~^^^NNFBB@!12?-!88?__ooww{{}!41~^NFFB@!147?NFB@!281?-!72?___oooww{{{}}!43~^NNFFBB@!440?-!53?!4_ooowww{{{}}}!46~^^NNFFBB@@@!450?-!33?___!4owww!4{}}}!49~^^^NNFFFBBB@@!464?-!21?_oww{}}}!50~^^^!4NFFFBBB@@@!481?-!13?__ow{}}!35~!4^!4N!4F!5B@@@!501?-!7?oow{}~~!12^!7N!7F!5B!5@!526?-!576?'
BANNER_SIXEL_LIGHT='"1;1;576;144#1;2;0;0;0-!576?-!126?!5_!5o!5w!7{!11}~~~^NNFB@!408?-!104?___ooo!4w!4{!4}!33~^NFBB@!415?-!85?___ooowww{{{!4}!44~^^^NFFB@!423?-!70?__oooww{{{}}}!43~^^^NNN!4FBBB@@@!434?-!56?___ooww{{}}!42~^^^NNNFFFBBB@@!453?-!45?_ooww{{}}!40~^^NNNFFBBB@@!470?-!35?_oow{{}}!38~^^NNFFBB@@@!104?_oowww!55{[KC!5?_ow!66{[KC!19?_o!16{o_!39?!13{wo__!42?!13{!5?CK!65{wwoo_!12?-!27?_ow{{}!37~^^NFFBB@@!112?_o{}!54~^NNFB@!5?_ow{}!63~^NFB@!18?_ow}!22~{w_!35?!18~}{{wo_!35?!13~!8?@BF!67~}wo!8?-!20?_ow{}!37~^NFBB@!122?w!14~NBB!40@!11?!31@B!13~!23@!19?_ow}!13~^NFN!14~}wo_!30?!26~}{woo_!27?!13~!11?!14~!36@BBBFN^!15~{!6?-!16?_o{}!36~^FB@!27?!5_!5o!25w!4o!5_!59?N!14~}{w!43o__!38?!13~!37?_ow{!14~NFB@!5?@BN^!13~}{w_!26?!13~BFNN^!15~}}{wo__!19?!13~!11?!14~!43?!15~!6?-!15?{!37~^B!18?_ooWW[[[]]M!10N!7^!34~}}{{{wwo__!46?@FN^!60~}{w_!32?!13~!33?ow{}!13~^NB@!15?BFN!14~{wo!22?!13~!6?@@BFNN^!15~}{wwo_!12?!13~!11?!14~!43?!15~!6?-!15?N!37~{_!49?@@BFFN!36~}{wo!46?@BBB!42FNN^!14~}!31?!13~!28?ow{}!13~^NF@!24?@BN^!13~}{o_!17?!13~!14?@@BFNN^!15~}{woo_!4?!13~!11?!14~!43?!15~!6?-!17?@BNN^!34~}}{wwwooo!6_!12?!7_oOO!18?v!39~w!91?_o!15~!31?!13~!23?_w{}!13~^NFB!34?BFN!13~}{w_!13?!13~!22?@@BFNN^!14~}{{!13~!11?!14~!38?__ow}!14~^!6?-!24?@BBBFFNNN!5^!35~!4^!4NFFFBBB@@!18?_ow}!38~^N!40?__ow{{}!59~^NB!31?!12~^!18?_o{}!14~NFB@!42?@BN^!13~}wo_!8?!13~!30?@@BFNN^!22~!11?!67~^NF@!7?-!43?!23@!33?__oow{}!39~^NF@!34?_oow{}}!58~^^^NNFB@@!34?!5~^NNFB@!15?ow{}!14~^FB@!52?BFN^!12~}{o_!4?!13~!38?@BBFN^^!14~!11?^!56~^^^NNFBB@!12?-!88?__ooww{{}!41~^NFFB@!147?NFB@!281?-!72?___oooww{{{}}!43~^NNFFBB@!440?-!53?!4_ooowww{{{}}}!46~^^NNFFBB@@@!450?-!33?___!4owww!4{}}}!49~^^^NNFFFBBB@@!464?-!21?_oww{}}}!50~^^^!4NFFFBBB@@@!481?-!13?__ow{}}!35~!4^!4N!4F!5B@@@!501?-!7?oow{}~~!12^!7N!7F!5B!5@!526?-!576?'
# <<< BANNER-ART-END

_ui_level=0
_ui_theme="dark"
_ui_utf8=0
case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *UTF-8*|*utf8*|*utf-8*) _ui_utf8=1 ;;
esac

ui_detect() {
    case "${NEBFLOW_UI_LEVEL:-}" in
        0|1|2|3) _ui_level="${NEBFLOW_UI_LEVEL}" ;;
        *)
            _ui_level=0
            if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ -z "${CI:-}" ] && [ "${TERM:-dumb}" != "dumb" ]; then
                case "${COLORTERM:-}" in
                    truecolor|24bit) _ui_level=3 ;;
                    *) case "${TERM:-}" in
                           *256color*) _ui_level=2 ;;
                           *)         _ui_level=1 ;;
                       esac ;;
                esac
            fi
            ;;
    esac
    case "${NEBFLOW_BANNER_THEME:-}" in
        dark|light) _ui_theme="${NEBFLOW_BANNER_THEME}" ;;
        *)
            _ui_theme="dark"
            if [ -n "${COLORFGBG:-}" ]; then
                local _bg="${COLORFGBG##*;}"
                case "$_bg" in
                    ''|*[!0-9]*) : ;;
                    *) [ "$_bg" -ge 7 ] 2>/dev/null && _ui_theme="light" ;;
                esac
            fi
            ;;
    esac
}

# -- banner image path ----------------------------------------------------------
# Dual-path (2026-10-22 batch): a terminal that speaks an inline-image
# protocol renders the REAL official raster instead of the block art. Every
# escape byte is produced here; the embedded payloads stay pure printable
# ASCII (the sixel bodies are single-quoted - their 0x3F-0x7E charset can
# never hold a quote).

_banner_image_mode() {  # -> _b_img="off"|"osc"|"sixel"; fail-closed
    _b_img="off"
    case "${NEBFLOW_BANNER_IMAGE:-auto}" in
        off|0|no) return ;;
        osc|iterm) _b_img="osc"; return ;;   # forced: testing overrides guards
        sixel|wt)  _b_img="sixel"; return ;;
        auto|""|yes|1|on) : ;;
        *) return ;;                          # unknown value: fail closed
    esac
    # auto honors the same guards as the color levels: a redirected pipe or
    # a no-color contract must never receive sixel/OSC bytes.
    if [ -n "${NO_COLOR:-}" ] || [ -n "${CI:-}" ] \
        || [ "${TERM:-dumb}" = "dumb" ] || ! [ -t 1 ]; then
        return
    fi
    case "${TERM_PROGRAM:-}" in
        iTerm.app|WezTerm|mintty) _b_img="osc"; return ;;
    esac
    if [ "${KONSOLE_VERSION:-0}" -ge 220401 ] 2>/dev/null; then
        _b_img="osc"; return                 # Konsole >= 22.04 renders OSC 1337
    fi
    case "${WT_SESSION:-}" in
        '') : ;;
        *) _b_img="sixel" ;;                 # Windows Terminal >= 1.22 (2025-04+)
    esac
}

_banner_emit_image() {  # one-shot: the official raster in _b_img's protocol
    if [ "$_ui_theme" = "light" ]; then
        _b_png="$BANNER_PNG_LIGHT"; _b_sx="$BANNER_SIXEL_LIGHT"
    else
        _b_png="$BANNER_PNG_DARK";  _b_sx="$BANNER_SIXEL_DARK"
    fi
    if [ "$_b_img" = "osc" ]; then
        # OSC 1337 inline image; width/height in CELLS. 72x9 cells is
        # physically 4:1 (a cell is ~1:2 w:h) = the lockup's own aspect, on
        # the same footprint as the half-block art (72 cols x 9 half-block
        # rows). name= (base64 per the spec) is not decorative: iTerm2's
        # "allow terminal to display this file?" approval keys on it - a
        # named file is remembered once, an unnamed one can prompt again on
        # every run.
        printf '\033]1337;File=name=c3RhbmQtbG9nby5wbmc=;inline=1;width=72;height=9:%s\007' "$_b_png"
    else
        # sixel: DCS (aspect default; P2=1 transparent; grid default), the
        # pre-encoded body (raster attrs + palette + RLE bands, canvas
        # 576 x ~144 px = the same 72x9-cell footprint at an ~8x16 cell),
        # ST.
        printf '\033P0;1;0q'
        printf '%s' "$_b_sx"
        printf '\033\\'
    fi
}

# -- banner painters (art fallback path) ---------------------------------------
# Glyph bytes are produced with printf octal escapes (POSIX: dash has neither
# $'\u' nor \u in printf): U+2580 upper half = \342\226\200, U+2584 lower
# half = \342\226\204, U+2588 full = \342\226\210. Ink is painted with the
# FOREGROUND color (empty cells stay untouched terminal background), one
# printf per row.

_banner_glyph_init() {
    _g_u=$(printf '\342\226\200')
    _g_n=$(printf '\342\226\204')
    _g_f=$(printf '\342\226\210')
}

_banner_fg_init() {
    _b_rst=""
    _b_dim=""
    _b_fg=""
    case "$_ui_level" in
        3)
            if [ "$_ui_theme" = "dark" ]; then _b_ink="$BANNER_INK_DARK"
            else _b_ink="$BANNER_INK_LIGHT"; fi
            _b_fg=$(printf '\033[38;2;%sm' "$_b_ink")
            _b_rst=$(printf '\033[0m'); _b_dim=$(printf '\033[2m') ;;
        2)  # nearest xterm-256: white 231, black 16
            if [ "$_ui_theme" = "dark" ]; then _b_fg=$(printf '\033[38;5;231m')
            else _b_fg=$(printf '\033[38;5;16m'); fi
            _b_rst=$(printf '\033[0m'); _b_dim=$(printf '\033[2m') ;;
        1)  # 16-color nearest: bright white 97 / black 30
            if [ "$_ui_theme" = "dark" ]; then _b_fg=$(printf '\033[97m')
            else _b_fg=$(printf '\033[30m'); fi
            _b_rst=$(printf '\033[0m'); _b_dim=$(printf '\033[2m') ;;
    esac
}

_banner_row() {  # <rle-row> -> stdout: one visible banner row
    _b_rest="$1"
    _b_out=""
    _b_num=""
    while [ -n "$_b_rest" ]; do
        _b_c="${_b_rest%"${_b_rest#?}"}"
        _b_rest="${_b_rest#?}"
        case "$_b_c" in
            [0-9]) _b_num="${_b_num}${_b_c}" ;;
            [un#.])
                if [ "$_ui_level" = 0 ]; then
                    if [ "$_b_c" = "." ]; then _b_g=" "; else _b_g="#"; fi
                else
                    case "$_b_c" in
                        "u") _b_g="$_g_u" ;;
                        "n") _b_g="$_g_n" ;;
                        "#") _b_g="$_g_f" ;;
                        *)   _b_g=" " ;;
                    esac
                fi
                _b_i=0
                while [ "$_b_i" -lt "$_b_num" ]; do
                    _b_out="${_b_out}${_b_g}"
                    _b_i=$((_b_i+1))
                done
                _b_num="" ;;
        esac
    done
    printf '%s' "$_b_out"
}

print_banner() {
    ui_detect
    # The half-block glyphs are UTF-8 (U+2580/U+2584/U+2588): without a UTF-8
    # locale the banner degrades to mono, the same rule the progress bar's
    # eighth-blocks follow. (A NEBFLOW_UI_LEVEL override re-enables color
    # explicitly - preview/testing wins over the locale heuristic.)
    if [ "$_ui_utf8" != 1 ] && [ -z "${NEBFLOW_UI_LEVEL:-}" ]; then
        _ui_level=0
    fi
    _banner_image_mode
    printf '\n'
    if [ "$_b_img" != "off" ]; then
        # Image path: the REAL logo raster replaces the block art. The
        # version line still sits under the mark, subordinate typography.
        _banner_emit_image
        if [ "$_ui_level" -ge 1 ]; then
            printf '  \033[2m%s installer (%s)\033[0m\n' "${VERSION:-dev}" "${CHANNEL:-stable}"
        else
            printf '  %s installer (%s)\n' "${VERSION:-dev}" "${CHANNEL:-stable}"
        fi
        printf '\n'
        return
    fi
    _banner_glyph_init
    _banner_fg_init
    _b_rest="$BANNER_ART"
    while [ -n "$_b_rest" ]; do
        case "$_b_rest" in
            *';'*) _b_row="${_b_rest%%;*}"; _b_rest="${_b_rest#*;}" ;;
            *)     _b_row="$_b_rest"; _b_rest="" ;;
        esac
        if [ "$_ui_level" -ge 1 ]; then
            printf '  %s%s%s\n' "$_b_fg" "$(_banner_row "$_b_row")" "$_b_rst"
        else
            printf '  %s\n' "$(_banner_row "$_b_row")"
        fi
    done
    # Version line sits under the art, dim, left-aligned to the lockup edge -
    # typography stays subordinate to the official mark (batch mandate).
    printf '  %s%s installer (%s)%s\n' "$_b_dim" "${VERSION:-dev}" "${CHANNEL:-stable}" "$_b_rst"
    printf '\n'
}

# -- download progress --------------------------------------------------------
# Clean single-line bar in brand green: percentage only when content-length
# is known (unknown length -> spinner + byte count, never a fake %), current
# file label, size/speed. In-place \r redraw, COLUMNS-adaptive. Non-TTY
# (curl|bash pipe) / TERM=dumb: no control output at all, plain log lines.

_progress_ok() {
    [ -t 1 ] && [ "${TERM:-dumb}" != "dumb" ] && command -v curl > /dev/null 2>&1
}

_fmt_bytes() {  # <bytes> -> "12.3M" / "640K" / "512B"
    awk -v b="${1:-0}" 'BEGIN{
        if (b >= 1048576) printf "%.1fM", b/1048576;
        else if (b >= 1024) printf "%.0fK", b/1024;
        else printf "%dB", b;
    }'
}

_bar() {  # <done> <total|-1> <width> -> bar body (no newline)
    local _done=$1 _total=$2 _w=$3
    local _e=0 _filled=0 _frac=0 _i _out=""
    if [ "$_total" -gt 0 ] 2>/dev/null; then
        _e=$(( _done * _w * 8 / _total ))
        [ "$_e" -gt $((_w*8)) ] && _e=$((_w*8))
        _filled=$((_e/8)); _frac=$((_e%8))
    fi
    local _g="" _r="" _d=""
    # POSIX: dash does not interpret $'\033...' (it yields the 9 literal bytes
    # "$'\033[32m"), so the same escape bytes are produced by the file's
    # existing printf idiom - identical byte sequences, no color change.
    case "$_ui_level" in
        3) _g=$(printf '\033[38;2;7;193;96m') ;;
        2) _g=$(printf '\033[38;5;35m') ;;
        1) _g=$(printf '\033[32m') ;;
    esac
    if [ -n "$_g" ]; then _r=$(printf '\033[0m'); _d=$(printf '\033[2m'); fi
    _out="$_g"
    if [ "$_ui_utf8" = 1 ]; then
        # eighth-block partials give sub-cell precision. POSIX: the table is
        # selected by case instead of an array (index 0 was the empty string
        # and was unreachable anyway - it sits behind the _frac > 0 guard), and
        # the three counting loops are while-loops: same iteration counts,
        # same append order, same bytes.
        local _part
        _i=0
        while [ "$_i" -lt "$_filled" ]; do _out="${_out}█"; _i=$((_i+1)); done
        if [ "$_frac" -gt 0 ]; then
            case "$_frac" in
                1) _part="▏" ;;
                2) _part="▎" ;;
                3) _part="▍" ;;
                4) _part="▌" ;;
                5) _part="▋" ;;
                6) _part="▊" ;;
                *) _part="▉" ;;
            esac
            _out="${_out}${_part}"; _filled=$((_filled+1))
        fi
        _out="${_out}${_r}${_d}"
        _i=$_filled
        while [ "$_i" -lt "$_w" ]; do _out="${_out}░"; _i=$((_i+1)); done
    else
        _i=0
        while [ "$_i" -lt "$_filled" ]; do _out="${_out}#"; _i=$((_i+1)); done
        if [ "$_frac" -gt 0 ]; then _out="${_out}>"; _filled=$((_filled+1)); fi
        _out="${_out}${_r}"
        _i=$_filled
        while [ "$_i" -lt "$_w" ]; do _out="${_out}-"; _i=$((_i+1)); done
    fi
    _out="${_out}${_r}"
    printf '%s' "$_out"
}

# Compose one full progress line (colors included). Pure function of its
# arguments - also driven by scripts/preview-brand-ui.sh for static frames.
_progress_line() {  # <done> <total|-1> <label> <speed_Bps|-1> <spin_idx>
    local _done=$1 _total=$2 _label=$3 _spd=$4 _spin=$5
    local _cols=${COLUMNS:-80}
    local _info=" $(_fmt_bytes "$_done")"
    [ "$_total" -gt 0 ] 2>/dev/null && _info="${_info}/$(_fmt_bytes "$_total")"
    [ "$_spd" -ge 0 ] 2>/dev/null && _info="${_info}  $(_fmt_bytes "$_spd")/s"
    local _pct
    if [ "$_total" -gt 0 ] 2>/dev/null; then
        _pct=$(awk -v d="$_done" -v t="$_total" 'BEGIN{p=int(d*100/t); printf "%3d%%", (p>100?100:p)}')
    else
        # POSIX: dash has no ${var:off:len}, and it is fatal there ("Bad
        # substitution"), so the 4-cell spinner table is selected by case.
        # Cell order and the surrounding padding are unchanged.
        local _s_ch
        case "$((_spin % 4))" in
            0) _s_ch='|' ;;
            1) _s_ch='/' ;;
            2) _s_ch='-' ;;
            *) _s_ch='\' ;;
        esac
        _pct="  ${_s_ch} "
    fi
    local _w=$(( _cols - ${#_label} - ${#_info} - 16 ))
    [ "$_w" -lt 10 ] && _w=10
    [ "$_w" -gt 48 ] && _w=48
    printf '  %s %s%s  %s' "$_pct" "$(_bar "$_done" "$_total" "$_w")" "$_info" "$_label"
}

progress_render() {  # <done> <total|-1> <label> <speed_Bps|-1> <spin_idx>
    _progress_ok || return 0
    printf '\r\033[K%s' "$(_progress_line "$@")"
}
# <<< BRAND-UI-END <<<

# ---- [1/6] environment ----------------------------------------------------
detect_os() {
    local uname_out="$(uname -s 2>/dev/null)"
    case "$uname_out" in
        Darwin*) OS_FAMILY="mac" ;;
        Linux*)  OS_FAMILY="linux" ;;
        MINGW*|MSYS*|CYGWIN*) OS_FAMILY="windows" ;;
        *)       OS_FAMILY="unknown" ;;
    esac
}

detect_arch() {
    case "$(uname -m)" in
        arm64|aarch64) ARCH="arm64" ;;
        *)             ARCH="x64" ;;
    esac
}

# Auto-detect region: check if user is in China
detect_region() {
    if [ -n "$REGION" ]; then
        return 0  # already set by --cn or --global flag
    fi
    # Method 1: check system timezone
    # POSIX: never write `&> /dev/null` for a probe. dash splits it into a
    # backgrounded probe plus a bare redirect, so the test is always true and
    # the real result is lost (rg/java/curl would all read as "present").
    local tz=""
    if [ -f /etc/timezone ]; then
        tz=$(cat /etc/timezone 2>/dev/null)
    elif command -v timedatectl > /dev/null 2>&1; then
        tz=$(timedatectl show -p Timezone 2>/dev/null | cut -d= -f2)
    fi
    case "$tz" in
        Asia/Shanghai|Asia/Chongqing|Asia/Hong_Kong|Asia/Taipei|Asia/Macau|PRC|Asia/Urumqi)
            REGION="cn"
            return 0
            ;;
    esac

    # Method 2: check LANG/LC_ALL for a zh_* locale
    case "${LANG:-}${LC_ALL:-}" in
        *zh_CN*|*zh_TW*|*zh_HK*)
            REGION="cn"
            return 0
            ;;
    esac

    # Method 3: probe an ACTUAL mirror object, not just the bucket root.
    # Latency alone cannot distinguish "fast bucket, empty prefix" from a
    # working mirror - that exact blind spot is how an empty deps/ prefix
    # went unnoticed for 18 days while installs quietly fell back overseas.
    # The cn verdict now requires the mirror to (a) answer HTTP 200/206,
    # (b) actually deliver the probed byte, and (c) still be fast vs GitHub.
    local cos_ms=99999 gh_ms=99999 cos_code=000 cos_bytes=0 probe_out=""
    if command -v curl > /dev/null 2>&1; then
        probe_out=$(curl -o /dev/null -s -r 0-0 \
            -w '%{http_code} %{time_total} %{size_download}' \
            --connect-timeout 2 --max-time 4 \
            "${COS_DEPS_BASE}/checksums.txt" 2>/dev/null || true)
        cos_code=$(printf '%s' "$probe_out" | awk '{print $1}')
        cos_ms=$(printf '%s' "$probe_out" | awk '{printf "%d", $2 * 1000}')
        cos_bytes=$(printf '%s' "$probe_out" | awk '{print $3}')
        cos_code=${cos_code:-000}; cos_ms=${cos_ms:-99999}; cos_bytes=${cos_bytes:-0}
        gh_ms=$(curl -o /dev/null -s -w '%{time_total}' --connect-timeout 2 --max-time 3 \
            "https://github.com/favicon.ico" 2>/dev/null | \
            awk '{printf "%d", $1 * 1000}')
        gh_ms=${gh_ms:-99999}
    fi

    # cn requires the probed object byte to be actually fetchable AND fast:
    # a fast but 404 prefix must read as global so installs go straight to
    # the upstream sources instead of probing a dead mirror first.
    if { [ "$cos_code" = "200" ] || [ "$cos_code" = "206" ]; } \
        && [ "$cos_bytes" -ge 1 ] 2>/dev/null \
        && [ "$cos_ms" -lt 500 ] && [ "$cos_ms" -lt $((gh_ms / 2)) ]; then
        REGION="cn"
    else
        REGION="global"
    fi
}

detect_pkg_mgr() {
    PKG_MGR=""
    local m
    for m in apt-get dnf yum apk; do
        if command -v "$m" > /dev/null 2>&1; then PKG_MGR="$m"; break; fi
    done
    if [ -n "$PKG_MGR" ]; then
        log_i "Package manager: ${PKG_MGR}"
    else
        log_v "No known package manager found (apt/dnf/yum/apk)"
    fi
}

stage_env() {
    stage_hdr 1 "Checking environment..."
    detect_os
    detect_arch
    log_i "OS: ${OS_FAMILY} (${ARCH})"
    if [ "$OS_FAMILY" = "unknown" ]; then
        log_err "Unsupported platform: $(uname -s 2>/dev/null || echo unknown)"
        exit 1
    fi
    if [ "$OS_FAMILY" = "windows" ]; then
        log_err "Windows detected - use install.ps1 (PowerShell) instead of install.sh."
        exit 1
    fi
    detect_region
    log_i "Region: ${REGION} (use --cn or --global to override)"
    if [ "$OS_FAMILY" = "linux" ]; then
        detect_pkg_mgr
    fi
}

# ---- [2/6] dependencies ---------------------------------------------------

_java_ok() {
    command -v java > /dev/null 2>&1 || return 1
    local v
    v=$(java -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f1)
    [ "$v" = "1" ] && v=$(java -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f2)
    [ "$v" -ge "$JDK_MAJOR_REQUIRED" ] 2>/dev/null
}

java_manual_hint() {
    log_err "Manual install: https://adoptium.net/temurin/releases/?version=21"
    log_err "Then re-run this installer."
}

# Region-gated Homebrew source combo (cn): the installer bootstrap only solves
# step 1 (bootstrap); brew's own git repos are pinned to the official
# upstreams, and the bottle domain redirects package payloads. All three are
# environment variables consumed by brew at runtime.
# macOS brew mirror switch is DEFERRED by author ruling (2026-09-25,
# installmirror batch): domestic bottle mirrors serve their roots (200) but
# the standard openjdk@21 bottle names all 404 and none of them offers a
# sha256 surface - switching without a verifiable checksum source would break
# the integrity-no-compromise rule. Unlock condition: a usable bottle
# checksum source (separate batch).
configure_homebrew_mirrors() {
    if [ "$REGION" = "cn" ]; then
        export HOMEBREW_BREW_GIT_REMOTE="https://github.com/Homebrew/brew.git"
        export HOMEBREW_CORE_GIT_REMOTE="https://github.com/Homebrew/homebrew-core.git"
        export HOMEBREW_BOTTLE_DOMAIN="https://ghcr.io/v2/homebrew/core"
        log_v "Homebrew git remotes + bottle domain set (official upstreams)"
    fi
}

ensure_brew() {
    command -v brew > /dev/null 2>&1 && return 0
    log_i "Homebrew not found. Installing..."
    # Xcode CLT is a Homebrew prerequisite; trigger it if absent
    if ! xcode-select -p > /dev/null 2>&1; then
        log_warn "Xcode Command Line Tools missing - triggering install (a dialog may appear; re-run this script after it finishes)."
        xcode-select --install > /dev/null 2>&1 || true
    fi
    configure_homebrew_mirrors
    local installer_done=0
    local tmp_installer
    tmp_installer=$(mktemp /tmp/${LOWER_NAME}-brew-install-XXXXXX.sh)
    if [ "$REGION" = "cn" ]; then
        # 1) COS snapshot of the installer (batch 2) - no GitHub dependency
        log_i "Fetching Homebrew installer from COS mirror (cn)..."
        if curl -fsSL --connect-timeout 8 --max-time 30 \
            "${COS_DEPS_BASE}/homebrew-install.sh" -o "$tmp_installer" 2>/dev/null; then
            if bash "$tmp_installer"; then installer_done=1; fi
        fi
        # 2) git clone of the installer repo
        if [ "$installer_done" = "0" ] && command -v git > /dev/null 2>&1; then
            log_i "Fetching Homebrew installer via git clone (cn)..."
            rm -rf /tmp/${LOWER_NAME}-homebrew-install
            if git clone --depth 1 https://github.com/Homebrew/install.git \
                /tmp/${LOWER_NAME}-homebrew-install > /dev/null 2>&1; then
                if bash /tmp/${LOWER_NAME}-homebrew-install/install.sh; then installer_done=1; fi
                rm -rf /tmp/${LOWER_NAME}-homebrew-install
            fi
        fi
    fi
    rm -f "$tmp_installer"
    # 3) Official installer (raw.githubusercontent.com; needs overseas access)
    if [ "$installer_done" = "0" ]; then
        log_i "Fetching official Homebrew installer..."
        /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)" || return 1
    fi
    # Make brew visible in this session (prefix derived, not hardcoded —
    # covers both Apple Silicon and Intel layouts, including a brew the
    # installer just placed but did not export into this shell)
    local brew_pfx
    brew_pfx="$(brew_prefix)"
    if [ -n "$brew_pfx" ]; then
        eval "$("$brew_pfx/bin/brew" shellenv)" 2>/dev/null || export PATH="$brew_pfx/bin:$PATH"
    fi
    command -v brew > /dev/null 2>&1
}

# Homebrew prefix resolver — derived, not hardcoded. One prescription, both
# call sites ([2026-09-14 coupling audit · plan A]: the former hardcoded
# macOS/Apple-Silicon-only prefix literal is replaced by this derivation;
# the /usr/local fallback is the pre-existing Intel default, a standard Unix
# prefix and not a macOS-only one).
# Contract: non-empty output <=> "$prefix/bin/brew" is executable; always
# returns 0 (brew absent/unavailable => empty string => caller no-ops, same
# as before). Legs 1-2 consume state the caller may not have; leg 3 is the
# absolute-path probe that covers the first-install window (brew just placed
# by the installer — a child process — so not yet on PATH and no prefix
# variable exported into this shell).
brew_prefix() {
    # 1) explicit env override (portable; caller/CI may inject it)
    if [ -n "${HOMEBREW_PREFIX:-}" ] && [ -x "${HOMEBREW_PREFIX}/bin/brew" ]; then
        printf '%s' "$HOMEBREW_PREFIX"
        return 0
    fi
    # 2) brew on PATH: ask brew itself (correct prefix on Apple Silicon and Intel)
    if command -v brew > /dev/null 2>&1; then
        local p
        p="$(brew --prefix 2>/dev/null)"
        if [ -n "$p" ] && [ -x "$p/bin/brew" ]; then
            printf '%s' "$p"
            return 0
        fi
    fi
    # 3) per-architecture install roots, probed by absolute path (needs neither
    #    PATH nor any prefix variable). Vendor-neutral glob first — that is the
    #    Apple Silicon layout — then the pre-existing Intel default below; this
    #    keeps the preference order the hardcoded form had.
    local c
    for c in /opt/*/bin/brew; do
        [ -x "$c" ] || continue
        printf '%s' "${c%/bin/brew}"
        return 0
    done
    # 4) pre-existing Intel default prefix fallback
    if [ -x /usr/local/bin/brew ]; then
        printf '%s' "/usr/local"
        return 0
    fi
    printf '%s' ""
    return 0
}

link_brew_jdk() {
    # brew openjdk@21 needs a symlink into /Library/Java/JavaVirtualMachines
    local prefix
    prefix="$(brew_prefix)"
    if [ -z "$prefix" ] || [ ! -d "${prefix}/opt/openjdk@21" ]; then
        return 0
    fi
    sudo ln -sfn "${prefix}/opt/openjdk@21/libexec/openjdk.jdk" \
        /Library/Java/JavaVirtualMachines/openjdk-21.jdk 2>/dev/null || true
    export PATH="${prefix}/opt/openjdk@21/bin:$PATH"
}

ensure_java_mac_tarball() {
    # macOS twin of ensure_java_linux_tarball: deps/ mirror -> TUNA -> Adoptium
    # API, sha256 via deps/checksums.txt. Mac tarballs nest the JDK under
    # Contents/Home - normalize into the pinned layout ${STAND_BASE}/jdk-21
    # (staging swap: a corrupt/truncated download never replaces the pin slot).
    local jdk_arch="aarch64"
    [ "$ARCH" = "x64" ] && jdk_arch="x64"
    local jdk_ver="21.0.12.1_1"
    local tarball_name="OpenJDK21U-jdk_${jdk_arch}_mac_hotspot_${jdk_ver}.tar.gz"
    local jdk_dir="${STAND_BASE}/jdk-21"
    mkdir -p "${STAND_BASE}" || return 1
    local tmp_tar tmp_dir
    # NOTE (siteinstall-exec acceptance fix): no .tar.gz suffix on the mktemp
    # template - BSD mktemp (macOS) only randomizes TRAILING X's; with a
    # suffix it silently creates the literal fixed name, so a reinstall or a
    # concurrent install collides on /tmp and this leg hard-fails. The linux
    # twin (GNU mktemp) accepts suffixes; the mac leg must not copy that form.
    tmp_tar=$(mktemp /tmp/${LOWER_NAME}-jdk-XXXXXX)
    tmp_dir=$(mktemp -d)
    local tuna_url="https://mirrors.tuna.tsinghua.edu.cn/Adoptium/21/jdk/${jdk_arch}/mac/${tarball_name}"
    local jdk_url="https://api.adoptium.net/v3/binary/latest/21/ga/mac/${jdk_arch}/jdk/hotspot/normal/eclipse"
    if ! download_file "$tmp_tar" "$tarball_name" "$tarball_name" \
        "${COS_DEPS_BASE}/${tarball_name}" "$tuna_url" "$jdk_url"; then
        rm -f "$tmp_tar"; rm -rf "$tmp_dir"; return 1
    fi
    if ! tar xzf "$tmp_tar" -C "$tmp_dir" 2>/dev/null; then
        rm -f "$tmp_tar"; rm -rf "$tmp_dir"; return 1
    fi
    rm -f "$tmp_tar"
    local src
    src=$(find "$tmp_dir" -type d -path '*/Contents/Home' 2>/dev/null | head -1)
    if [ -z "$src" ] || [ ! -x "${src}/bin/java" ]; then
        rm -rf "$tmp_dir"; return 1
    fi
    local major
    major=$("${src}/bin/java" -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f1)
    [ "$major" = "1" ] && major=$("${src}/bin/java" -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f2)
    case "$major" in ''|*[!0-9]*) rm -rf "$tmp_dir"; return 1 ;; esac
    [ "$major" -ge "$JDK_MAJOR_REQUIRED" ] 2>/dev/null || { rm -rf "$tmp_dir"; return 1; }
    # staging swap into the pin slot (same-filesystem rename, legacy tree only
    # removed after the new tree is fully in place)
    rm -rf "${jdk_dir}.new.$$"
    if ! mv "${src}" "${jdk_dir}.new.$$" 2>/dev/null; then rm -rf "$tmp_dir"; return 1; fi
    rm -rf "$tmp_dir"
    rm -rf "$jdk_dir"
    if ! mv "${jdk_dir}.new.$$" "$jdk_dir" 2>/dev/null; then
        rm -rf "${jdk_dir}.new.$$"; return 1
    fi
    export PATH="$jdk_dir/bin:$PATH"
    export JAVA_HOME="$jdk_dir"
    return 0
}

ensure_java_mac() {
    # cn: Temurin tarball first (deps/ mirror -> TUNA; readings 2026-10-07:
    # ghcr bottle 39-354 KB/s vs TUNA ~3 MB/s) - Homebrew demoted to fallback,
    # so a fresh domestic Mac never touches github.com/ghcr.io for Java.
    # global: brew-first unchanged (ghcr is fast overseas); the tarball leg
    # becomes the new failure fallback instead of a hard exit.
    # NEBFLOW_JDK_TARBALL=1 forces the tarball leg on any region (testing).
    if { [ "$REGION" = "cn" ] || [ "${NEBFLOW_JDK_TARBALL:-}" = "1" ]; } \
        && ensure_java_mac_tarball; then
        log_ok "Java installed (Temurin tarball, pinned at ~/${HOME_DIR}/jdk-21)."
        return 0
    fi
    ensure_brew || {
        log_err "Could not install Homebrew; trying the Temurin tarball leg..."
        if ensure_java_mac_tarball; then
            log_ok "Java installed (Temurin tarball, pinned at ~/${HOME_DIR}/jdk-21)."
            return 0
        fi
        log_err "Tarball leg failed as well."
        java_manual_hint
        exit $ERR_JAVA
    }
    log_i "Installing OpenJDK 21 via Homebrew..."
    if ! brew install --quiet openjdk@21; then
        log_err "brew install openjdk@21 failed - trying the Temurin tarball leg..."
        if ensure_java_mac_tarball; then
            log_ok "Java installed (Temurin tarball, pinned at ~/${HOME_DIR}/jdk-21)."
            return 0
        fi
        java_manual_hint
        exit $ERR_JAVA
    fi
    link_brew_jdk
}

ensure_java_linux_tarball() {
    # Fallback when distro packages are unavailable/failed. Source chain:
    # 1) our own deps/ mirror (same Temurin build, sha256 via checksums.txt)
    # 2) TUNA Adoptium mirror (domestic direct, fast; no sidecar checksum -
    #    integrity rides on the manifest + the byte-identical upstream build)
    # 3) Adoptium API (overseas last resort)
    local jdk_arch="x64"
    [ "$ARCH" = "arm64" ] && jdk_arch="aarch64"
    local jdk_ver="21.0.12.1_1"
    local tarball_name="OpenJDK21U-jdk_${jdk_arch}_linux_hotspot_${jdk_ver}.tar.gz"
    local jdk_dir="${STAND_BASE}/jdk-21"
    mkdir -p "${STAND_BASE}"
    local tmp_tar
    tmp_tar=$(mktemp /tmp/${LOWER_NAME}-jdk-XXXXXX.tar.gz)
    local tuna_url="https://mirrors.tuna.tsinghua.edu.cn/Adoptium/21/jdk/${jdk_arch}/linux/${tarball_name}"
    local jdk_url="https://api.adoptium.net/v3/binary/latest/21/ga/linux/${jdk_arch}/jdk/hotspot/normal/eclipse"
    if download_file "$tmp_tar" "$tarball_name" "$tarball_name" \
        "${COS_DEPS_BASE}/${tarball_name}" "$tuna_url" "$jdk_url"; then
        tar xzf "$tmp_tar" -C "${STAND_BASE}" 2>/dev/null
        rm -f "$tmp_tar"
        local extracted
        extracted=$(ls -d "${HOME}"/${HOME_DIR}/jdk-21* 2>/dev/null | head -1)
        if [ -n "$extracted" ]; then
            mv "$extracted" "$jdk_dir" 2>/dev/null || true
            export PATH="$jdk_dir/bin:$PATH"
            export JAVA_HOME="$jdk_dir"
            return 0
        fi
    else
        rm -f "$tmp_tar"
    fi
    return 1
}

ensure_java_linux() {
    local installed_any=0
    # cn order (installmirror batch, recon R5.3): the TUNA-mirrored tarball
    # goes BEFORE the distro packager - packagers need sudo and their sources
    # are outside our control; global keeps the packager-first order.
    if [ "$REGION" = "cn" ]; then
        log_i "Installing OpenJDK 21 from the TUNA Adoptium mirror (cn)..."
        if ensure_java_linux_tarball; then
            log_ok "Java installed (TUNA mirror tarball)."
            return 0
        fi
        log_v "TUNA tarball unavailable - falling back to the distro package manager."
    fi
    case "$PKG_MGR" in
        apt-get)
            log_i "Installing OpenJDK 21 via apt..."
            sudo apt-get update -qq && sudo apt-get install -y openjdk-21-jdk-headless 2>&1 || true
            installed_any=1
            ;;
        dnf)
            log_i "Installing OpenJDK 21 via dnf..."
            sudo dnf install -y java-21-openjdk-devel 2>&1 || true
            installed_any=1
            ;;
        yum)
            log_i "Installing OpenJDK 21 via yum..."
            sudo yum install -y java-21-openjdk-devel 2>&1 || true
            installed_any=1
            ;;
        apk)
            log_i "Installing OpenJDK 21 via apk..."
            sudo apk add --no-cache openjdk21 2>&1 || true
            installed_any=1
            ;;
    esac
    log_v "pkg-mgr install attempted=${installed_any}"
    if ! _java_ok; then
        log_i "Package manager unavailable or failed - falling back to Temurin JDK 21 tarball..."
        if ! ensure_java_linux_tarball; then
            log_err "Java auto-install did not succeed."
            java_manual_hint
            exit $ERR_JAVA
        fi
    fi
}

ensure_java() {
    if _java_ok; then
        log_ok "Java: $(java -version 2>&1 | head -n1)"
        return 0
    fi
    log_i "Java ${JDK_MAJOR_REQUIRED}+ not found. Installing OpenJDK 21..."
    case "$OS_FAMILY" in
        mac)   ensure_java_mac ;;
        linux) ensure_java_linux ;;
    esac
    if _java_ok; then
        log_ok "Java installed: $(java -version 2>&1 | head -n1)"
    else
        log_err "Java auto-install did not succeed."
        java_manual_hint
        exit $ERR_JAVA
    fi
}

ensure_curl() {
    if command -v curl > /dev/null 2>&1; then
        log_v "curl: $(curl --version 2>/dev/null | head -1 | cut -d' ' -f1-2)"
        return 0
    fi
    if command -v wget > /dev/null 2>&1; then
        log_warn "curl missing - wget found, downloads will use wget."
        return 0
    fi
    log_i "Installing curl..."
    case "$PKG_MGR" in
        apt-get) sudo apt-get update -qq && sudo apt-get install -y curl 2>&1 || true ;;
        dnf)     sudo dnf install -y curl 2>&1 || true ;;
        yum)     sudo yum install -y curl 2>&1 || true ;;
        apk)     sudo apk add --no-cache curl 2>&1 || true ;;
    esac
    if command -v curl > /dev/null 2>&1 || command -v wget > /dev/null 2>&1; then
        log_ok "Downloader available."
    else
        log_err "Neither curl nor wget is available and none could be installed."
        exit $ERR_CURL
    fi
}

rg_soft_fail() {
    # Non-fatal: search falls back to a PATH-installed rg at runtime
    log_warn "rg could not be installed automatically - search support may be degraded."
    local tarball_name
    if [ "$OS_FAMILY" = "mac" ]; then
        log_warn "Manual install: brew install ripgrep"
        if [ "$ARCH" = "arm64" ]; then
            tarball_name="ripgrep-${RG_VERSION}-aarch64-apple-darwin.tar.gz"
        else
            tarball_name="ripgrep-${RG_VERSION}-x86_64-apple-darwin.tar.gz"
        fi
    else
        log_warn "Manual install: ${PKG_MGR:-apt-get} install ripgrep"
        tarball_name="ripgrep-${RG_VERSION}-x86_64-unknown-linux-musl.tar.gz"
    fi
    # Upstream ripgrep tags are BARE ("14.1.1"), never "v14.1.1": the old
    # `tag/v${RG_VERSION}` form 404s (tagfix 2026-09-17, curl -I readings).
    log_warn "Manual download: https://github.com/BurntSushi/ripgrep/releases/tag/${RG_VERSION}"
    log_warn "Manual placement: extract 'rg' to ${INSTALL_DIR}/rg (chmod +x)"
    expected_checksum_hint "$tarball_name" || true
}

_install_rg_tarball() {
    # $1 = upstream platform suffix (apple-darwin | unknown-linux-musl)
    local tarball_name="ripgrep-${RG_VERSION}-${1}.tar.gz"
    local gh_url="https://github.com/BurntSushi/ripgrep/releases/download/${RG_VERSION}/${tarball_name}"
    local tmp_archive tmp_dir rg_bin
    tmp_archive=$(mktemp)
    tmp_dir=$(mktemp -d)
    log_i "Downloading rg ${RG_VERSION} (${1})..."
    # Source chain: our deps/ mirror -> ghproxy -> GitHub upstream.
    # ghproxy (~16 KB/s measured) and upstream (~14 KB/s) are both slow - the
    # real fix is the populated deps/ mirror (restored 2026-09-25); ghproxy is
    # promoted over upstream only because upstream is slower AND unreachable
    # on some domestic networks.
    if ! download_file "$tmp_archive" "$tarball_name" "$tarball_name" \
        "${COS_DEPS_BASE}/${tarball_name}" "https://ghproxy.net/${gh_url}" "$gh_url"; then
        rm -rf "$tmp_archive" "$tmp_dir"
        return 1
    fi
    # Portable extraction (GNU tar AND bsdtar): unpack, then find the binary.
    # INSTALL_DIR is NOT guaranteed to exist here: ensure_rg runs in stage_deps,
    # one stage BEFORE download_jar (which creates the dir via version_dir) -
    # a fresh install previously died at this cp (dormant until seed-first made
    # this channel load-bearing, envfix batch 2026-09-21).
    mkdir -p "${INSTALL_DIR}" || return 1
    if tar xzf "$tmp_archive" -C "$tmp_dir" 2>/dev/null; then
        rg_bin=$(find "$tmp_dir" -type f -name rg -perm -u+x 2>/dev/null | head -1)
        [ -z "$rg_bin" ] && rg_bin=$(find "$tmp_dir" -type f -name rg 2>/dev/null | head -1)
        if [ -n "$rg_bin" ]; then
            cp "$rg_bin" "${INSTALL_DIR}/rg" && chmod +x "${INSTALL_DIR}/rg"
        fi
    fi
    rm -rf "$tmp_archive" "$tmp_dir"
    if [ -x "${INSTALL_DIR}/rg" ]; then
        log_ok "rg installed to ${INSTALL_DIR}/rg"
        return 0
    fi
    return 1
}

_install_rg_distro() {
    case "$PKG_MGR" in
        apt-get) sudo apt-get update -qq && sudo apt-get install -y ripgrep 2>&1 || true ;;
        dnf)     sudo dnf install -y ripgrep 2>&1 || true ;;
        yum)     sudo yum install -y ripgrep 2>&1 || true ;;
        apk)     sudo apk add --no-cache ripgrep 2>&1 || true ;;
        *)       return 1 ;;
    esac
    command -v rg > /dev/null 2>&1
}

# Seed ${INSTALL_DIR}/rg from the rg currently on PATH. Install-time PATH is
# the login shell's, so a hit here is the host's working rg; cp dereferences
# brew-style symlinks (sources resolve through ../Cellar/...). The seeded
# copy is sanity-run before we trust it - a PATH entry that is a broken
# wrapper/script must fall through to the installer channels instead of
# seeding garbage. Offline-safe: zero download.
_seed_rg_from_path() {
    local _rg_hit
    _rg_hit=$(command -v rg 2>/dev/null) || return 1
    [ -n "$_rg_hit" ] && [ -f "$_rg_hit" ] || return 1
    mkdir -p "${INSTALL_DIR}" || return 1
    if cp "$_rg_hit" "${INSTALL_DIR}/rg" 2>/dev/null && chmod 755 "${INSTALL_DIR}/rg" \
        && "${INSTALL_DIR}/rg" --version > /dev/null 2>&1; then
        log_ok "rg: seeded ${_rg_hit} -> ${INSTALL_DIR}/rg"
        return 0
    fi
    rm -f "${INSTALL_DIR}/rg"
    log_warn "rg: seed from ${_rg_hit} failed sanity check - trying installer channels..."
    return 1
}

ensure_rg() {
    if [ -x "${INSTALL_DIR}/rg" ]; then
        log_ok "rg: cached at ${INSTALL_DIR}/rg"
        return 0
    fi
    # Seed-first (author ruling 2026-09-21, envfix batch): a PATH hit no longer
    # short-circuits without seeding. The seeded copy at ${INSTALL_DIR}/rg is
    # the ONLY leg a service-context runtime (launchd/systemd minimal PATH) can
    # rely on - incident 2026-09-21: host launched by launchd with
    # PATH=/usr/bin:/bin:/usr/sbin:/sbin saw no rg anywhere (readings:
    # .nebflow/evidence/20260921_env-rg-restore/). Re-entry stays idempotent:
    # the cached check above returns before any write.
    local installed=0
    if command -v rg > /dev/null 2>&1; then
        # if-form, not `&&`: the script runs under `set -e` (pipe installs use
        # dash), and a failing AND-list statement would abort the whole install
        # instead of falling through to the installer channels.
        if _seed_rg_from_path; then installed=1; fi
    fi
    if [ "$installed" = "0" ]; then
        log_i "Installing ripgrep (rg) for search support..."
        case "$OS_FAMILY" in
            mac)
                if [ "$ARCH" = "arm64" ]; then
                    _install_rg_tarball "aarch64-apple-darwin" && installed=1
                else
                    _install_rg_tarball "x86_64-apple-darwin" && installed=1
                fi
                ;;
            linux)
                if [ "$ARCH" = "arm64" ]; then
                    # No official aarch64-linux tarball upstream (verified 404,
                    # 2026-09-06) - use the distro package instead.
                    if _install_rg_distro; then installed=1; log_ok "rg installed via ${PKG_MGR}"; fi
                else
                    if _install_rg_tarball "x86_64-unknown-linux-musl"; then
                        installed=1
                    elif _install_rg_distro; then
                        installed=1; log_ok "rg installed via ${PKG_MGR}"
                    fi
                fi
                ;;
        esac
    fi
    # A distro install lands rg on the system PATH, NOT in ${INSTALL_DIR} -
    # seed it from there so the install-dir invariant below holds on every
    # success path (update re-entry included: the same pipeline re-runs).
    if [ ! -x "${INSTALL_DIR}/rg" ] && command -v rg > /dev/null 2>&1; then
        if _seed_rg_from_path; then installed=1; fi
    fi
    # Success invariant is the seeded copy itself, not a channel's exit code.
    if [ ! -x "${INSTALL_DIR}/rg" ]; then
        rg_soft_fail
    fi
}

# Download Whisper voice model for offline speech recognition (best-effort)
install_voice_model() {
    local model_dir="${STAND_BASE}/voice-models/onnx-community/whisper-base"
    if [ -f "$model_dir/onnx/encoder_model_quantized.onnx" ]; then
        log_v "Voice model already installed."
        return 0
    fi

    local base
    if [ "$REGION" = "cn" ]; then
        base="https://hf-mirror.com/onnx-community/whisper-base/resolve/main"
    else
        base="https://huggingface.co/onnx-community/whisper-base/resolve/main"
    fi
    log_i "Downloading Whisper voice model (~75MB, one-time)..."
    mkdir -p "$model_dir/onnx"

    # Config files (small) - [n/N] multi-file counter in the label
    local _n=0 _total_files=6
    local f
    for f in config.json tokenizer.json generation_config.json preprocessor_config.json; do
        _n=$((_n+1))
        _download "$base/$f" "$model_dir/$f" "[$_n/$_total_files] $f" 2>/dev/null || true
    done

    # Quantized ONNX models (encoder ~22MB + decoder ~51MB)
    local ok=true
    _n=$((_n+1))
    _download "$base/onnx/encoder_model_quantized.onnx" "$model_dir/onnx/encoder_model_quantized.onnx" \
        "[$_n/$_total_files] encoder_model_quantized.onnx" || ok=false
    _n=$((_n+1))
    _download "$base/onnx/decoder_model_merged_quantized.onnx" "$model_dir/onnx/decoder_model_merged_quantized.onnx" \
        "[$_n/$_total_files] decoder_model_merged_quantized.onnx" || ok=false
    if $ok; then
        log_ok "Voice model installed."
    else
        log_warn "Voice model download failed (voice will use CDN on first use)."
    fi
}

stage_deps() {
    stage_hdr 2 "Checking dependencies..."
    ensure_curl
    ensure_java
    ensure_rg
    install_voice_model
}

# ---- [3/6] jar ------------------------------------------------------------

_file_size() { stat -c %s "$1" 2>/dev/null || stat -f %z "$1" 2>/dev/null || echo 0; }

# A JAR that is already present only counts as "up to date" when it is a
# COMPLETE archive: a truncated file (interrupted download, dropped link) would
# otherwise be reported as already-installed and never repaired. Semantics
# follow the released installer's _jar_valid - size floor + ZIP structural
# check - EXCEPT when no zip tool (unzip, python3) exists at all: there the
# bytes cannot be checked in any way, so the file is reported invalid and the
# installer re-downloads instead of trusting a magic-byte probe (rather slow
# than wrong). download_jar warns about that case when it happens.
_jar_valid() {  # <path> -> 0 when the file looks like a complete JAR
    local _path="$1" _size
    [ -f "$_path" ] && [ -s "$_path" ] || return 1
    _size=$(wc -c < "$_path" 2>/dev/null || echo 0)
    [ "${_size:-0}" -ge 1000000 ] || return 1
    if command -v unzip > /dev/null 2>&1; then
        unzip -t "$_path" > /dev/null 2>&1
        return $?
    fi
    if command -v python3 > /dev/null 2>&1; then
        python3 -c 'import sys,zipfile; sys.exit(0 if zipfile.is_zipfile(sys.argv[1]) else 1)' "$_path" 2>/dev/null
        return $?
    fi
    # Last resort: no zip tool at all (neither unzip nor python3) -> the bytes
    # cannot be verified. An unverifiable file is NOT a trusted file: report it
    # invalid so the caller re-downloads ("rather slow than wrong" - see the
    # warning in download_jar for the cost this implies in such environments).
    return 1
}

# TTY download with the brand progress bar: curl runs in the background
# writing to the target file; we poll its size and redraw the bar. Total
# size comes from a HEAD probe (content-length); unreachable -> spinner mode.
_download_progress() {  # <url> <target> <label> -> curl exit code
    local _url="$1" _target="$2" _label="$3"
    local _total
    _total=$(curl -fsSI --connect-timeout 5 --max-time 10 "$_url" 2>/dev/null \
        | tr -d '\r' | awk 'tolower($1)=="content-length:"{n=$2} END{if(n!="") printf "%d", n}')
    [ -z "$_total" ] && _total=-1
    curl -fsSL --connect-timeout 10 --max-time 120 "$_url" -o "$_target" 2>/dev/null &
    local _pid=$! _spin=0 _last=0 _now=0 _spd=-1
    while kill -0 "$_pid" 2>/dev/null; do
        _now=$(_file_size "$_target")
        _spd=$(( (_now - _last) * 2 ))   # 0.5s poll interval
        _last=$_now
        progress_render "$_now" "$_total" "$_label" "$_spd" "$_spin"
        _spin=$((_spin+1))
        sleep 0.5 2>/dev/null || sleep 1
    done
    local _rc=0
    wait "$_pid" || _rc=$?
    _now=$(_file_size "$_target")
    progress_render "$_now" "$_total" "$_label" -1 "$_spin"
    printf '\n'
    return "$_rc"
}

_download() {
    local url="$1" target="$2" label="${3:-}"
    if _progress_ok; then
        _download_progress "$url" "$target" "${label:-$(basename "$target")}"
    else
        # non-TTY (curl|bash pipe) / dumb terminal: plain one-line log
        [ -n "$label" ] && log_i "Downloading ${label}..."
        if command -v curl > /dev/null 2>&1; then
            curl -fsSL --connect-timeout 10 --max-time 120 "${url}" -o "${target}"
        elif command -v wget > /dev/null 2>&1; then
            wget --connect-timeout=10 --timeout=120 -q "${url}" -O "${target}"
        else
            log_err "curl or wget is required."
            exit $ERR_CURL
        fi
    fi
}

# ---- checksum machinery (deps/ integrity, batch 2) ------------------------

CHECKSUMS_LOADED=""
CHECKSUMS_CONTENT=""
CHECKSUMS_STATE=""   # ok | unreachable | unparseable (set once, on first load)

sha256_of() {  # <file> -> hash (or empty when no tool available)
    if command -v shasum > /dev/null 2>&1; then
        shasum -a 256 "$1" 2>/dev/null | awk '{print $1}'
    elif command -v sha256sum > /dev/null 2>&1; then
        sha256sum "$1" 2>/dev/null | awk '{print $1}'
    fi
}

# Load deps/checksums.txt ONCE, in the CALLER's shell: subshell semantics
# mean assignments made inside $( fetch_checksum_for ... ) die with the
# subshell, so the load must happen before any command substitution (the
# subshell then inherits the loaded state). Callers: download_file and
# expected_checksum_hint (both run where the cache must live).
load_checksums_once() {
    [ -n "$CHECKSUMS_LOADED" ] && return 0
    CHECKSUMS_LOADED=1
    local raw
    raw=$(curl -fsSL --connect-timeout 5 --max-time 15 \
        "${COS_DEPS_BASE}/checksums.txt" 2>/dev/null || true)
    if [ -n "$raw" ]; then
        # Keep only well-formed "sha256  name" rows: a fetched-but-garbage
        # body must degrade as "unparseable" (a visible warning), never as
        # a working manifest that silently verifies nothing.
        CHECKSUMS_CONTENT=$(printf '%s\n' "$raw" | \
            grep -E '^[0-9a-fA-F]{64}[[:space:]]+[^[:space:]]+$' || true)
        if [ -n "$CHECKSUMS_CONTENT" ]; then
            CHECKSUMS_STATE="ok"
            log_v "Loaded deps/checksums.txt from the mirror."
        else
            CHECKSUMS_STATE="unparseable"
            log_v "deps/checksums.txt fetched but unparseable - checksum verification degraded."
        fi
    else
        CHECKSUMS_STATE="unreachable"
        log_v "deps/checksums.txt unreachable - checksum verification degraded."
    fi
}

# Pure lookup over the loaded manifest (safe inside $():
# <filename> -> expected sha256 (or empty = unknown)
fetch_checksum_for() {
    [ -n "$CHECKSUMS_CONTENT" ] || return 0
    # POSIX: no here-strings in dash; printf '%s\n' reproduces the exact
    # here-string payload (value + one trailing newline) for awk on stdin.
    printf '%s\n' "$CHECKSUMS_CONTENT" | awk -v f="$1" '$2 == f { print $1; exit }'
}

expected_checksum_hint() {  # <filename> -> "sha256: <hash>" line (or empty)
    local h
    load_checksums_once
    h=$(fetch_checksum_for "$1")
    [ -n "$h" ] && echo "       sha256: ${h}"
}

# Policy gate for "no verification possible" verdicts (NEBFLOW_VERIFY:
# strict|warn|off, default warn). Returns 0 when the install may proceed
# despite the unverified artifact; 1 = refuse it (strict). Degraded
# verification is NEVER silent: warn prints a visible [warn] line (once per
# manifest-level cause, per artifact otherwise); off still prints a one-time
# notice; strict rejects so download_file falls through to the next source.
# The reason travels as an argument (stdout protocol of verify_checksum):
# globals set inside $( verify_checksum ... ) would die with the subshell.
accept_unverified() {  # <name> <reason>
    local name="$1" reason="$2"
    case "$VERIFY_MODE" in
        off)
            if [ -z "${VERIFY_OFF_NOTED:-}" ]; then
                log_warn "Integrity verification disabled by NEBFLOW_VERIFY=off - downloads are NOT checksum-verified."
                VERIFY_OFF_NOTED=1
            fi
            return 0 ;;
        strict) return 1 ;;
    esac
    case "$reason" in
        manifest-unreachable|manifest-unparseable)
            if [ -z "${VERIFY_WARN_MANIFEST_NOTED:-}" ]; then
                if [ "$reason" = "manifest-unreachable" ]; then
                    log_warn "Checksum manifest unreachable (${COS_DEPS_BASE}/checksums.txt) => this install performs NO integrity verification on third-party deps."
                else
                    log_warn "Checksum manifest fetched but unparseable (${COS_DEPS_BASE}/checksums.txt) => this install performs NO integrity verification on third-party deps."
                fi
                log_warn "Fix the mirror and re-run, or set NEBFLOW_VERIFY=strict to refuse unverified installs."
                VERIFY_WARN_MANIFEST_NOTED=1
            fi
            ;;
        no-sha-tool)
            log_warn "No sha256 tool (shasum/sha256sum) found - cannot verify ${name}; installed unverified. Set NEBFLOW_VERIFY=strict to refuse unverified installs."
            ;;
        *)
            log_warn "${name} has no entry in deps/checksums.txt - installed unverified. Set NEBFLOW_VERIFY=strict to refuse unverified installs."
            ;;
    esac
    return 0
}

# Multi-source download with checksum verification. Every candidate source
# (mirror first by convention) is verified against deps/checksums.txt; a
# mismatched source is discarded and the next one is tried. "No verification
# possible" is a policy decision (NEBFLOW_VERIFY), never a silent default:
# warn = visible warning + accept, strict = reject and try the next source,
# off = skip with a one-time notice.
#   download_file <target> <filename-in-manifest> <label> <url1> [url2] ...
download_file() {
    local target="$1" name="$2" label="$3"; shift 3
    local url verdict reason
    load_checksums_once   # in THIS shell, so every $( verify_checksum )
                          # subshell below inherits the loaded manifest
    for url in "$@"; do
        log_v "Trying source: ${url}"
        if _download "$url" "$target" "$label"; then
            verdict=$(verify_checksum "$target" "$name") || true
            case "$verdict" in
                ok)      return 0 ;;
                bad)     rm -f "$target"; continue ;;
                unknown*)
                    reason=${verdict#unknown }
                    if accept_unverified "$name" "$reason"; then return 0; fi
                    rm -f "$target"; continue ;;
            esac
        else
            rm -f "$target"
        fi
    done
    return 1
}

verify_checksum() {  # <file> <filename-in-manifest> -> echoes "ok" | "bad"
                     # | "unknown <reason>" where <reason> is one of:
                     # manifest-unreachable | manifest-unparseable |
                     # no-sha-tool | not-in-manifest
    # The reason rides on stdout (not a global): this function is consumed
    # via $( ), and assignments inside a subshell cannot reach the caller.
    local file="$1" name="$2" expected actual
    load_checksums_once
    expected=$(fetch_checksum_for "$name")
    if [ -z "$expected" ]; then
        case "$CHECKSUMS_STATE" in
            ok)          echo "unknown not-in-manifest" ;;
            unparseable) echo "unknown manifest-unparseable" ;;
            *)           echo "unknown manifest-unreachable" ;;
        esac
        return 0
    fi
    actual=$(sha256_of "$file")
    if [ -z "$actual" ]; then
        echo "unknown no-sha-tool"   # no sha256 tool - degrade, don't misjudge
        return 0
    fi
    if [ "$actual" = "$expected" ]; then
        echo "ok"
        return 0
    fi
    echo "bad"
    return 0
}

download_jar() {
    stage_hdr 3 "Downloading ${PRODUCT_NAME} ${VERSION}..."
    # Version-dependent names are computed here (VERSION resolves in
    # resolve_version, before this stage runs).
    JAR_NAME="${LOWER_NAME}-assembly-${VERSION}.jar"
    COS_URL="${COS_BASE_CN}/${JAR_NAME}"
    local target_versioned prev_now
    target_versioned="$(version_dir "${VERSION}")/${JAR_NAME}"
    mkdir -p "$(version_dir "${VERSION}")"
    # The version currently installed is read BEFORE archiving moves the legacy
    # root jar away (otherwise the rollback target would be lost on upgrade from
    # a pre-G4 install).
    prev_now=$(current_version_now)

    # Idempotency: same version already in place -> skip (no re-download).
    # Presence alone is not enough: a truncated/corrupt file must fall through
    # to the repair path below instead of being reported as up-to-date (and
    # silently installed). return, never exit - the pipeline must continue.
    if [ -f "${target_versioned}" ] && _jar_valid "${target_versioned}"; then
        log_ok "Already up-to-date (${VERSION})."
        archive_legacy_jars
        record_version "${VERSION}" "${prev_now}"
        return 0
    fi

    # Version retention (batch 2 G4): old packages are MOVED into their version
    # dir instead of being deleted - the previous version must survive on disk to
    # serve as the rollback base (design 6-2: keeping the last two versions is the
    # one new on-disk mechanism of this face). User data stays untouched.
    archive_legacy_jars

    # 统一更新系统 M3 ③（engine manifest era）：引擎侧已按官网 manifest 的
    # sha256/sizeBytes 逐字节校验过的 jar 可经 NEBFLOW_STAGED_JAR 交接进来——
    # 采用前**本侧再验一次 sha256**（NEBFLOW_EXPECTED_JAR_SHA256；双向都不信任
    # 未验哈希的字节，防交接窗内文件被换）；验不过/变量缺席 ⇒ 自然落到下方既有
    # 下载源，零行为回归。cp 进版本目录后同目录 rename（跨盘交接不产生撕裂文件）。
    if [ -n "${NEBFLOW_STAGED_JAR:-}" ] && [ -f "${NEBFLOW_STAGED_JAR}" ]; then
        _staged_sha=$(sha256_of "${NEBFLOW_STAGED_JAR}")
        if [ -n "${_staged_sha}" ] && [ "${_staged_sha}" = "${NEBFLOW_EXPECTED_JAR_SHA256:-}" ]; then
            if cp -f "${NEBFLOW_STAGED_JAR}" "${target_versioned}.staged" \
                && mv -f "${target_versioned}.staged" "${target_versioned}"; then
                log_ok "Adopted engine-verified staged JAR (sha256 ok)."
                record_version "${VERSION}" "${prev_now}"
                return 0
            fi
            rm -f "${target_versioned}.staged"
            log_warn "Staged JAR adoption failed - falling back to download."
        else
            log_warn "Staged JAR sha256 mismatch (expected ${NEBFLOW_EXPECTED_JAR_SHA256:-<unset>}, got ${_staged_sha:-none}) - ignoring the handoff, downloading."
        fi
    fi

    # 单一源（结论不变）：jar 只从上面的镜像端点取。2026-09-17 更正：此前
    # 的「#29 仓库 private ⇒ GitHub Releases 未认证 404」理由已过时（仓库现已
    # 公开），单源理由为可达性与带宽，见文件头品牌值区注释。
    if _download "${COS_URL}" "${target_versioned}" "${JAR_NAME}"; then
        log_ok "Downloaded ${JAR_NAME} from COS."
        # Same no-zip-tool situation as in _jar_valid: the fresh bytes cannot be
        # verified either. Say so out loud - never let the log imply an
        # integrity check that did not happen - and carry on: failing here
        # would leave such an environment permanently uninstallable.
        if ! command -v unzip > /dev/null 2>&1 && ! command -v python3 > /dev/null 2>&1; then
            log_warn "No unzip or python3 found - cannot verify the downloaded JAR (${JAR_NAME}). Install continues unverified; a re-run will download it again."
        fi
        record_version "${VERSION}" "${prev_now}"
        return 0
    fi
    log_err "Download failed from COS. Check ${COS_URL}"
    exit $ERR_JAR
}

# ---- [4/6] wrapper + PATH -------------------------------------------------

# Version retention + pointer (batch 2 G4, design section 6-2): the ONE new
# on-disk mechanism of the auto-restart safety face. Layout:
#   <installDir>/current-version                      -> pointer, version to run
#   <installDir>/previous-version                     -> pointer, rollback target
#   <installDir>/versions/<version>/<jar>             -> one immutable dir per version
# Selection is POINTER-FIRST (never "the numerically newest file in the dir"):
# a bad version that is still on disk can therefore never be picked again after
# a rollback - it stays on disk (rollback base + forensics) but outside the
# selection face. Legacy installs without a pointer keep the old scan path
# byte-for-byte (see the wrapper below).
POINTER_CURRENT="${INSTALL_DIR}/current-version"
POINTER_PREVIOUS="${INSTALL_DIR}/previous-version"
VERSIONS_DIR="${INSTALL_DIR}/versions"

version_dir()  { printf '%s/%s' "${VERSIONS_DIR}" "$1"; }

# Version of a jar file name (nebflow-assembly-<version>.jar -> <version>).
jar_version() {  # <path> -> echoes version or nothing
    local _base="${1##*/}"
    case "$_base" in
        *-assembly-*.jar)
            _base="${_base##*-assembly-}"
            printf '%s' "${_base%.jar}"
            ;;
    esac
}

read_pointer() {  # <pointer path> -> echoes version or nothing
    [ -f "$1" ] || return 0
    tr -d ' \t\r\n' < "$1" 2>/dev/null || true
}

write_pointer() {  # <pointer path> <version>
    local _tmp="$1.tmp"
    printf '%s\n' "$2" > "$_tmp" 2>/dev/null || return 1
    mv -f "$_tmp" "$1" 2>/dev/null || return 1
}

# Move a legacy root-level jar into its version dir (retention, not deletion) so
# it can serve as the rollback base. Echoes the version when one was archived.
archive_legacy_jars() {
    local _f _v _vd
    for _f in "${INSTALL_DIR}"/${LOWER_NAME}-assembly-*.jar "${INSTALL_DIR}"/nebflow-assembly-*.jar; do
        [ -f "$_f" ] || continue
        _v=$(jar_version "$_f")
        [ -n "$_v" ] || continue
        _vd=$(version_dir "$_v")
        if [ ! -f "${_vd}/${_f##*/}" ]; then
            mkdir -p "$_vd" 2>/dev/null || continue
            mv -f "$_f" "${_vd}/" 2>/dev/null || continue
            log_i "Retained previous version ${_v} for rollback (${_vd})"
        else
            rm -f "$_f"
        fi
    done
}

# Current version per the pointer, falling back to the legacy root scan (so the
# retention logic also works for installs made by an older script).
current_version_now() {
    local _v
    _v=$(read_pointer "${POINTER_CURRENT}")
    if [ -z "$_v" ]; then
        _v=$(jar_version "$(ls -1 "${INSTALL_DIR}"/${LOWER_NAME}-assembly-*.jar "${INSTALL_DIR}"/nebflow-assembly-*.jar 2>/dev/null | head -n 1)")
    fi
    printf '%s' "$_v"
}

record_version() {  # <version> [<previous version>] - keep exactly two (current + previous)
    # ${2:-} (not "$2"): the second argument is optional and the installer itself
    # runs without `set -u` - read it defensively so the one-argument form
    # (legacy install: previous version derived from the pointer/root scan)
    # also works under `set -u` harnesses. No behaviour change otherwise.
    local _prev="${2:-}" _other _vd
    [ -n "$_prev" ] || _prev=$(current_version_now)
    if [ -n "$_prev" ] && [ "$_prev" != "$1" ]; then
        write_pointer "${POINTER_PREVIOUS}" "$_prev"
        log_i "Rollback target recorded: ${_prev}"
    fi
    write_pointer "${POINTER_CURRENT}" "$1"
    # Prune: keep the two pointer-named versions, drop every other version dir.
    _prev=$(read_pointer "${POINTER_PREVIOUS}")
    if [ -d "${VERSIONS_DIR}" ]; then
        for _vd in "${VERSIONS_DIR}"/*; do
            [ -d "$_vd" ] || continue
            _other="${_vd##*/}"
            if [ "$_other" = "$1" ] || [ "$_other" = "$_prev" ]; then
                continue
            fi
            log_v "Pruning version ${_other} (retention keeps current + previous)"
            rm -rf "$_vd"
        done
    fi
}

# Create wrapper script
create_wrapper() {
    local wrapper="${INSTALL_DIR}/${WRAPPER_NAME}"
    log_i "Creating wrapper script..."
    # Unquoted delimiter: ${LOWER_NAME}/${PRODUCT_NAME} expand NOW (generation
    # time, from the brand block above); runtime expansions are escaped as \$.
    # (Bug fix: the old quoted 'WRAPPER' delimiter emitted the variables as
    # literals, so the wrapper's jar glob never matched -> nebflow CLI dead.)
    cat > "${wrapper}" << WRAPPER
#!/bin/bash
SCRIPT_DIR="\$(cd "\$(dirname "\$0")" && pwd)"
# Java selection: the pinned JDK (jdk-21) wins; PATH java is only a fallback.
# A missing pinned JDK must NEVER degrade silently (author ruling 2026-09-21,
# envfix batch): warn loudly to stderr first, then fall back.
JAVA_BIN="${STAND_BASE}/jdk-21/bin/java"
if [ ! -x "\$JAVA_BIN" ]; then
    echo "WARN: ${PRODUCT_NAME} pinned JDK missing at \$JAVA_BIN - falling back to PATH java." >&2
    echo "      Repair: re-run the ${PRODUCT_NAME} installer (it restores jdk-21 under ${STAND_BASE})." >&2
    JAVA_BIN="\$(command -v java || true)"
fi
java_hint() {
    case "\$(uname -s)" in
        Darwin) echo "  Install: brew install openjdk@21" >&2 ;;
        Linux)  echo "  Install: sudo apt install openjdk-21-jdk-headless  (dnf/yum: java-21-openjdk, apk: openjdk21)" >&2 ;;
        *)      echo "  Install: https://adoptium.net/temurin/releases/?version=21" >&2 ;;
    esac
    echo "  Then re-run: ${WRAPPER_NAME} <command>" >&2
    }
if [ -z "\$JAVA_BIN" ]; then
    echo "ERROR: Java ${JDK_MAJOR_REQUIRED:-21}+ not found (no pinned JDK, none on PATH)." >&2
    java_hint
    exit ${ERR_JAVA:-11}
fi
JAVA_MAJOR="\$("\$JAVA_BIN" -version 2>&1 | awk -F '"' '/version/ {print \$2}' | cut -d'.' -f1)"
[ "\$JAVA_MAJOR" = "1" ] && JAVA_MAJOR="\$("\$JAVA_BIN" -version 2>&1 | awk -F '"' '/version/ {print \$2}' | cut -d'.' -f2)"
case "\$JAVA_MAJOR" in ''|*[!0-9]*) JAVA_MAJOR=0 ;; esac
if [ "\$JAVA_MAJOR" -lt ${JDK_MAJOR_REQUIRED:-21} ]; then
    echo "ERROR: Java ${JDK_MAJOR_REQUIRED:-21}+ required, found \$("\$JAVA_BIN" -version 2>&1 | head -n1)" >&2
    echo "       launcher java: \$JAVA_BIN" >&2
    java_hint
    exit ${ERR_JAVA:-11}
fi
# >>> WINSORT-BEGIN v1 (version-order jar pick) >>>
# Name order != version order: the date scheme deliberately strips leading zeros
# (Windows version fields reject them), so as plain strings "2026.10.5" sorts
# BEFORE "2026.9.19". Rank the candidates by the parsed numeric tuple and take
# the max. Version core = the SAME contract as packaging/app-version.sh:36
#   ([0-9]{4})\.([0-9]{1,2})\.([0-9]{1,2})(\.[0-9]+)?(-beta\.[0-9]+)?
# The optional 4th segment and the -beta.N tail carry the SAME meaning - the
# same-day sequence (O-3), i.e. the tuple's single 4th field: four segments =
# date core + sequence. (tagfix 2026-09-17: the segment is optional and still
# anchored inside the core, so a 5-field name stays unparseable and is excluded
# like any other unknown shape - no new segment semantics are introduced.)
# Legacy semver shapes (1.4.1-beta.56) are ranked by the same 4-field tuple, so
# the order is total and deterministic. A name that parses as neither is
# EXCLUDED - deliberately NO silent fall back to name order: the caller's
# existing "jar not found" error path then fires.
_winsort_jar_key() { # <jar path> -> fixed-width numeric key (year,month,day,seq); rc=1 if unparseable
  local _base="\${1:-}" _re
  _base="\${_base##*/}"
  _re='-assembly-([0-9]{4})\.([0-9]{1,2})\.([0-9]{1,2})(\.([0-9]+))?(-beta\.([0-9]+))?\.jar\$'
  if [[ \$_base =~ \$_re ]]; then
    printf '%04d%03d%03d%06d' "\$((10#\${BASH_REMATCH[1]}))" "\$((10#\${BASH_REMATCH[2]}))" "\$((10#\${BASH_REMATCH[3]}))" "\$((10#\${BASH_REMATCH[5]:-\${BASH_REMATCH[7]:-0}}))"
    return 0
  fi
  _re='-assembly-([0-9]+)\.([0-9]+)\.([0-9]+)(\.([0-9]+))?(-beta\.([0-9]+))?\.jar\$'
  if [[ \$_base =~ \$_re ]]; then
    printf '%04d%03d%03d%06d' "\$((10#\${BASH_REMATCH[1]}))" "\$((10#\${BASH_REMATCH[2]}))" "\$((10#\${BASH_REMATCH[3]}))" "\$((10#\${BASH_REMATCH[5]:-\${BASH_REMATCH[7]:-0}}))"
    return 0
  fi
  return 1
}
_winsort_pick_newest() { # stdin: one candidate path per line -> prints the newest one
  local _cand _key _best='' _best_key=''
  while IFS= read -r _cand; do
    [ -n "\$_cand" ] || continue
    _key=\$(_winsort_jar_key "\$_cand") || continue
    if [ -z "\$_best_key" ] || [ "\$_key" \> "\$_best_key" ]; then
      _best="\$_cand"; _best_key="\$_key"
    fi
  done
  [ -n "\$_best" ] && printf '%s\n' "\$_best"
  return 0
}
# <<< WINSORT-END v1 <<<

# >>> POINTER-SELECT-BEGIN v1 (batch 2 G4: rollback-capable selection) >>>
# The pointer file current-version decides which version runs; a rollback is a
# pointer switch, so a bad version that is still on disk is never picked again.
# Version dirs hold one immutable jar each.
# Strict: if the pointer names a package that is not on disk, we do NOT silently
# pick something else - the fallback scan below finds nothing (no root jars) and
# the existing "JAR not found" error path fires loudly.
JAR=""
if [ -f "\${SCRIPT_DIR}/current-version" ]; then
    _pv=\$(tr -d ' \t\r\n' < "\${SCRIPT_DIR}/current-version" 2>/dev/null)
    if [ -n "\$_pv" ] && [ -f "\${SCRIPT_DIR}/versions/\${_pv}/${LOWER_NAME}-assembly-\${_pv}.jar" ]; then
        JAR="\${SCRIPT_DIR}/versions/\${_pv}/${LOWER_NAME}-assembly-\${_pv}.jar"
    elif [ -n "\$_pv" ]; then
        for _cand in "\${SCRIPT_DIR}/versions/\${_pv}"/*.jar; do
            [ -f "\$_cand" ] || continue
            JAR="\$_cand"
            break
        done
    fi
fi
# <<< POINTER-SELECT-END v1 <<<

JAR=\${JAR:-\$(ls -1 "\${SCRIPT_DIR}"/${LOWER_NAME}-assembly-*.jar 2>/dev/null | _winsort_pick_newest)}
if [ -z "\$JAR" ]; then
    echo "ERROR: ${PRODUCT_NAME} JAR not found in \${SCRIPT_DIR}"
    exit 1
fi
exec "\$JAVA_BIN" --add-opens java.base/java.lang=ALL-UNNAMED -jar "\$JAR" "\$@"
WRAPPER
    chmod +x "${wrapper}"
    log_ok "Wrapper created: ${wrapper}"
    # Legacy command shim (2026-10-20 rename batch): "nebflow" is retired as
    # the command name; a thin shim keeps muscle memory and old scripts alive
    # - it warns on stderr, then forwards to the current wrapper. Fixed legacy
    # name by design (historical fact, same rule as rebrand.sh) - NOT
    # brand-derived, so it stays stable across future renames. Also replaces
    # any pre-rename real "nebflow" binary in INSTALL_DIR (overwrite > shadow).
    local shim="${INSTALL_DIR}/nebflow"
    cat > "${shim}" << SHIM
#!/bin/bash
echo "WARN: 'nebflow' is deprecated - the command is now '${WRAPPER_NAME}'. Forwarding..." >&2
exec "${INSTALL_DIR}/${WRAPPER_NAME}" "\$@"
SHIM
    chmod +x "${shim}"
    log_ok "Legacy shim created: ${shim} (deprecation notice, forwards to ${WRAPPER_NAME})"
}

# Add install dir to PATH in shell profile
setup_path() {
    local profile=""
    if [ -f "${HOME}/.zshrc" ]; then
        profile="${HOME}/.zshrc"
    elif [ -f "${HOME}/.bashrc" ]; then
        profile="${HOME}/.bashrc"
    elif [ -f "${HOME}/.bash_profile" ]; then
        profile="${HOME}/.bash_profile"
    fi
    # Retire legacy ~/.nebflow/bin PATH entries (再生治本批 2026-10-22): the
    # pre-switch default-home installer added them, and they keep shadowing the
    # new install dir (a leftover old wrapper keeps regenerating ~/.nebflow
    # state on every CLI run). Comment the entry out in place - user history is
    # preserved, nothing is deleted. The new line below is appended separately.
    if [ -n "$profile" ] && grep -q '^[[:space:]]*export PATH=.*\.nebflow/bin' "$profile" 2>/dev/null; then
        sed -i.bak-nebflow-path \
            's|^\([[:space:]]*export PATH=.*\.nebflow/bin.*\)$|# retired legacy home PATH entry (default home moved to ~/'"${HOME_DIR}"'): \1|' \
            "$profile" 2>/dev/null || true
        log_i "Retired legacy ~/.nebflow/bin PATH entry in $profile (backup: $profile.bak-nebflow-path)"
    fi
    local path_entry="${STAND_BASE}/bin"
    if [ -n "$profile" ] && ! grep -qF "${path_entry}" "$profile" 2>/dev/null; then
        echo "" >> "$profile"
        echo "# Added by ${PRODUCT_NAME} installer" >> "$profile"
        echo "export PATH=\"${path_entry}:\$PATH\"" >> "$profile"
        log_i "Added ${path_entry} to PATH in $profile"
    else
        log_v "PATH already configured."
    fi
}

stage_wrapper() {
    stage_hdr 4 "Writing launcher and PATH..."
    create_wrapper
    setup_path
}

# ---- [5/6] config ---------------------------------------------------------

# Create config template
create_config() {
    local config_dir="${STAND_BASE}"
    local config_file="${config_dir}/${CONFIG_FILE}"
    if [ ! -f "${config_file}" ]; then
        log_i "Creating default config at ${config_file}..."
        mkdir -p "${config_dir}"
        echo '{}' > "${config_file}"
        log_ok "Config created: ${config_file}"
    else
        log_v "Config already exists."
    fi
}

# Installer manifest (SCRIPT_VERSION + environment) for `nebflow update`
# and diagnostics. Overwritten on each (re)install.
write_manifest() {
    local manifest="${STAND_BASE}/install-manifest.json"
    mkdir -p "${STAND_BASE}"
    cat > "${manifest}" << MANIFEST
{
  "scriptVersion": "${SCRIPT_VERSION}",
  "product": "${PRODUCT_NAME}",
  "version": "${VERSION}",
  "channel": "${CHANNEL}",
  "region": "${REGION}",
  "os": "${OS_FAMILY}",
  "arch": "${ARCH}",
  "installDir": "${INSTALL_DIR}",
  "installedAt": "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
}
MANIFEST
    log_v "Manifest written: ${manifest}"
}

stage_config() {
    stage_hdr 5 "Setting up config..."
    create_config
    write_manifest
}

# ---- [6/6] done -----------------------------------------------------------

# Major version of the java the generated launcher will actually use (pinned
# jdk-21 first, PATH java as fallback); prints nothing when none is usable.
# Mirrors the resolution order written into the wrapper by create_wrapper().
_launcher_java_major() {
    local java_bin="${STAND_BASE}/jdk-21/bin/java"
    [ -x "$java_bin" ] || java_bin="$(command -v java 2>/dev/null || true)"
    [ -n "$java_bin" ] || return 0
    local v
    v=$("$java_bin" -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f1)
    if [ "$v" = "1" ]; then
        v=$("$java_bin" -version 2>&1 | awk -F '"' '/version/ {print $2}' | cut -d'.' -f2)
    fi
    case "$v" in ''|*[!0-9]*) return 0 ;; esac
    printf '%s' "$v"
}

stage_finish() {
    stage_hdr 6 "Done!"
    # Post-install re-verification: never print a success line when the java the
    # launcher will use is below the floor (this used to be a silent success).
    local launcher_major
    launcher_major=$(_launcher_java_major)
    if [ -z "$launcher_major" ] || [ "$launcher_major" -lt "$JDK_MAJOR_REQUIRED" ]; then
        log_err "Java ${JDK_MAJOR_REQUIRED}+ is required, but the launcher resolves to: ${launcher_major:-none}."
        java_manual_hint
        exit $ERR_JAVA
    fi
    echo ""
    echo "[ok] ${PRODUCT_NAME} ${VERSION} installed."
    echo "     Run: ${WRAPPER_NAME}"
    # Base display: keep the byte-stable "~/.stand" form for default installs;
    # a STAND_HOME-pinned base shows its absolute path (never the legacy root).
    if [ -n "${STAND_HOME:-}" ]; then
        echo "     Config: ${STAND_BASE}/${CONFIG_FILE}"
        echo "     Please restart your terminal or run: export PATH=\"${STAND_BASE}/bin:\$PATH\""
    else
        echo "     Config: ~/${HOME_DIR}/${CONFIG_FILE}"
        echo "     Please restart your terminal or run: export PATH=\"\$HOME/${HOME_DIR}/bin:\$PATH\""
    fi
}

# ---- pipeline -------------------------------------------------------------
# --banner-only dry mode: render the banner and exit BEFORE any network or
# install side effect (standalone render-function verification path; the
# normal install flow below is byte-identical to pre-batch behaviour).
if [ "${BANNER_ONLY:-0}" = "1" ] || [ "${NEBFLOW_BANNER_ONLY:-0}" = "1" ]; then
    print_banner
    exit 0
fi
resolve_version
print_banner
stage_env
stage_deps
download_jar
stage_wrapper
stage_config
stage_finish
